import sys
import signal
import numpy as np
from scipy.stats import rv_discrete

class CustomDist(rv_discrete):
    def _cdf(self, k):
        # CDF that never exceeds 0.99
        return np.minimum(k / 100.0, 0.99)
    def _ppf(self, q):
        # Use the parent ppf which uses bracket search
        return super()._ppf(q)

def timeout_handler(signum, frame):
    raise TimeoutError('ppf call timed out - infinite loop detected')

try:
    # Set a 5-second timeout
    signal.signal(signal.SIGALRM, timeout_handler)
    signal.alarm(5)

    dist = CustomDist()
    # Try to get ppf of 0.999 which is unattainable (max CDF is 0.99)
    result = dist.ppf(0.999)
    signal.alarm(0)  # Cancel timeout
    probe('ppf_hangs', 0)  # Completed without hanging
except TimeoutError:
    signal.alarm(0)
    probe('ppf_hangs', 1)  # Timed out - confirms hang
except RuntimeError as e:
    signal.alarm(0)
    if 'bracket' in str(e).lower():
        probe('ppf_hangs', -1)  # RuntimeError raised (fix behavior)
    else:
        probe('ppf_hangs', 0)  # Different error
except Exception as e:
    signal.alarm(0)
    probe('ppf_hangs', 0)  # Unexpected error

